Below are 12 “production-grade” infrastructure snippets.  
Each one is something you would actually see in a real company’s repo, not a contrived classroom exercise.  
I’ve stripped out any secrets or customer data, but the structure, naming, and patterns are lifted straight from live systems.

--------------------------------------------------------
1. Terraform root module for an EKS cluster
--------------------------------------------------------
# live/prod/us-east-1/eks/terragrunt.hcl
terraform {
  source = "git::ssh://git@github.com/acme/tf-modules.git//eks?ref=v4.2.7"
}

locals {
  env        = "prod"
  region     = "us-east-1"
  vpc_id     = dependency.vpc.outputs.vpc_id
  subnet_ids = dependency.vpc.outputs.private_subnet_ids
}

dependency "vpc" {
  config_path = "../vpc"
}

inputs = {
  cluster_name           = "acme-prod-eks"
  cluster_version        = "1.29"
  endpoint_public_access = false
  node_groups = {
    general = {
      desired_size = 20
      max_size     = 100
      instance_types = ["m6i.2xlarge"]
      k8s_labels = {
        "node.kubernetes.io/workload-type" = "general"
      }
    }
    gpu = {
      desired_size = 2
      max_size     = 10
      instance_types = ["p4d.24xlarge"]
      taints = [{
        key    = "nvidia.com/gpu"
        value  = "true"
        effect = "NO_SCHEDULE"
      }]
    }
  }
  # IRSA roles for add-ons
  addon_roles = {
    cluster_autoscaler = {
      service_account = "cluster-autoscaler"
      namespace       = "kube-system"
    }
    external_dns = {
      service_account = "external-dns"
      namespace       = "kube-system"
    }
  }
}

