2. Kubernetes HelmRelease for cert-manager
--------------------------------------------------------
apiVersion: helm.toolkit.fluxcd.io/v2beta2
kind: HelmRelease
metadata:
  name: cert-manager
  namespace: cert-manager
spec:
  interval: 10m
  chart:
    spec:
      chart: cert-manager
      version: "v1.14.2"
      sourceRef:
        kind: HelmRepository
        name: jetstack
        namespace: flux-system
  values
